    "servings": 4,
    "category": [
      "dessert"
    ],
    "image": "images/mealdb-53046.jpg",
    "isNutFree": true,
    "isGlutenFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": true,
    "isVegan": false,
