    "image": "images/mealdb-53131.jpg",
    "isNutFree": false,
    "isGlutenFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
