    "image": "images/mealdb-53286.jpg",
    "isNutFree": true,
    "isGlutenFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
